import ast, os, sys
root = sys.argv[1]
classes = {}  # name -> list of (file, bases)
for dp, dn, fn in os.walk(root):
    if '.git' in dp or 'node_modules' in dp: continue
    for f in fn:
        if not f.endswith('.py'): continue
        p = os.path.join(dp, f)
        rel = os.path.relpath(p, root)
        if '/tests/' in '/'+rel or f.startswith('test_') : continue
        try:
            tree = ast.parse(open(p, encoding='utf-8').read())
        except Exception:
            continue
        for node in ast.walk(tree):
            if isinstance(node, ast.ClassDef):
                bases = []
                for b in node.bases:
                    if isinstance(b, ast.Name): bases.append(b.id)
                    elif isinstance(b, ast.Attribute): bases.append(b.attr)
                classes.setdefault(node.name, []).append((rel, node.lineno, bases))
target = 'StockController'
found = set()
changed = True
while changed:
    changed = False
    for name, defs in classes.items():
        for rel, ln, bases in defs:
            if name not in found and any(b == target or b in found for b in bases):
                found.add(name); changed = True
for name in sorted(found):
    for rel, ln, bases in classes[name]:
        print(f"{name}\t{rel}:{ln}\tbases={','.join(bases)}")
